CREATE OR REPLACE FUNCTION public.validate_order_line_family_selection()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  fam public.catalogue_families%rowtype;
  opt public.catalogue_product_options%rowtype;
begin
  if new.family_id is null then
    if new.product_option_id is not null
       or new.requested_presentation is not null
       or new.brand_preference_mode is not null
       or new.requested_brand is not null
       or new.product_option_snapshot is not null
       or new.family_name_snapshot is not null then
      raise exception 'Family selection fields require family_id';
    end if;
    return new;
  end if;

  select * into fam
  from public.catalogue_families
  where family_id = new.family_id and active = true;

  if not found then
    raise exception 'Unknown or inactive catalogue family: %', new.family_id;
  end if;

  new.family_name_snapshot := fam.family_name;
  new.line_description := fam.family_name;

  if coalesce(array_length(fam.presentations,1),0) > 0 then
    if nullif(btrim(coalesce(new.requested_presentation,'')),'') is null then
      raise exception 'Presentation is required for family %', new.family_id;
    end if;
    if not (new.requested_presentation = any(fam.presentations)) then
      raise exception 'Presentation % is not controlled for family %', new.requested_presentation, new.family_id;
    end if;
  end if;

  if new.brand_preference_mode not in ('no_preference','specific_option','other_brand') then
    raise exception 'Invalid brand preference mode';
  end if;

  if new.brand_preference_mode = 'specific_option' then
    if new.product_option_id is null then
      raise exception 'Specific option selection requires product_option_id';
    end if;
    select * into opt
    from public.catalogue_product_options
    where id = new.product_option_id
      and family_id = new.family_id
      and active = true
      and psc_decision = 'APPROVE'
      and customer_selectable = true;
    if not found then
      raise exception 'Selected product option is not approved for customer selection';
    end if;
    if nullif(btrim(coalesce(new.requested_presentation,'')),'') is not null
       and nullif(btrim(coalesce(opt.presentation,'')),'') is not null
       and new.requested_presentation <> opt.presentation then
      raise exception 'Selected product option does not match requested presentation';
    end if;
    new.requested_brand := opt.brand;
    new.brand_model_snapshot := opt.exact_product_name;
    new.pack_snapshot := opt.pack;
    new.product_option_snapshot := jsonb_build_object(
      'product_option_id', opt.id,
      'exact_product_name', opt.exact_product_name,
      'brand', opt.brand,
      'presentation', opt.presentation,
      'pack', opt.pack
    );
  elsif new.brand_preference_mode = 'other_brand' then
    if new.product_option_id is not null then
      raise exception 'Other-brand request cannot carry product_option_id';
    end if;
    if nullif(btrim(coalesce(new.requested_brand,'')),'') is null then
      raise exception 'Other-brand request requires requested_brand';
    end if;
    new.product_option_snapshot := null;
    new.brand_model_snapshot := new.requested_brand;
  else
    if new.product_option_id is not null then
      raise exception 'No-preference request cannot carry product_option_id';
    end if;
    new.requested_brand := null;
    new.product_option_snapshot := null;
    new.brand_model_snapshot := 'No preference';
  end if;

  return new;
end;
$function$

submission_functions.function_definition:
CREATE OR REPLACE FUNCTION public.psc_submit_institutional_request(p_school_id uuid, p_submission_key uuid, p_lines jsonb, p_note text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_group uuid;
  v_order public.orders%rowtype;
  v_line jsonb;
  v_fingerprint text;
begin
  if v_uid is null or p_submission_key is null then raise exception 'Sign-in and submission key required'; end if;
  if exists(select 1 from public.memberships m join public.account_groups g on g.id=m.group_id
    where m.user_id=v_uid and g.slug='psc-demo-group') then raise exception 'Demo requests cannot be submitted'; end if;
  select s.group_id into v_group from public.schools s
    where s.id=p_school_id and s.active and private.can_access_school(s.id);
  if v_group is null then raise exception 'Site access not authorized'; end if;
  if jsonb_typeof(p_lines) is distinct from 'array' then raise exception 'Request lines must be an array'; end if;
  if jsonb_array_length(p_lines) not between 1 and 300 or octet_length(p_lines::text)>500000
    or char_length(coalesce(p_note,''))>10000 then raise exception 'Request exceeds supported limits'; end if;
  v_fingerprint := md5(jsonb_build_object('school',p_school_id,'lines',p_lines,'note',coalesce(p_note,''))::text);
  -- Serialize retries for the same user/key, including concurrent submissions.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_uid::text||p_submission_key::text,0));
  select * into v_order from public.orders where requested_by=v_uid and submission_key=p_submission_key;
  if found then
    if v_order.submission_fingerprint is distinct from v_fingerprint then raise exception 'Submission key was used for a different requirement'; end if;
    return jsonb_build_object('id',v_order.id,'order_number',v_order.order_number,'replayed',true);
  end if;
  for v_line in select value from jsonb_array_elements(p_lines) loop
    if jsonb_typeof(v_line) is distinct from 'object'
      or jsonb_typeof(v_line->'quantity') is distinct from 'number'
      or (v_line->>'quantity')::numeric not between 0.001 and 1000000
      or char_length(coalesce(v_line->>'line_description','')) not between 1 and 2000
    then raise exception 'Each line needs a description and a positive quantity'; end if;
  end loop;
  insert into public.orders(order_number,group_id,school_id,requested_by,status,note,channel,submission_key,submission_fingerprint)
  values('PSC-REQ-'||to_char(now(),'YYYYMM')||'-'||replace(p_submission_key::text,'-',''),
    v_group,p_school_id,v_uid,'under_review',coalesce(p_note,''),'institutional',p_submission_key,v_fingerprint)
  returning * into v_order;
  -- A line error rolls back the order AND its queued notification in this transaction.
  insert into public.order_lines(order_id,product_id,psc_sku_snapshot,line_description,brand_model_snapshot,
    pack_snapshot,quantity,family_id,family_name_snapshot,product_option_id,requested_presentation,
    brand_preference_mode,requested_brand,product_option_snapshot)
  select v_order.id,null,x.psc_sku_snapshot,x.line_description,x.brand_model_snapshot,x.pack_snapshot,
    x.quantity,x.family_id,x.family_name_snapshot,x.product_option_id,x.requested_presentation,
    case when x.family_id is not null then coalesce(x.brand_preference_mode,'no_preference') else x.brand_preference_mode end,x.requested_brand,x.product_option_snapshot
  from jsonb_to_recordset(p_lines) as x(psc_sku_snapshot text,line_description text,brand_model_snapshot text,
    pack_snapshot text,quantity numeric,family_id text,family_name_snapshot text,product_option_id uuid,
    requested_presentation text,brand_preference_mode text,requested_brand text,product_option_snapshot jsonb);
  return jsonb_build_object('id',v_order.id,'order_number',v_order.order_number,'replayed',false);
end;
$function$
